import{_ as r,l as n,o as e,c as l,v as i,p as s,x as t,d as E,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"转换效率的物理","description":"","frontmatter":{"title":"转换效率的物理","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/conversion-efficiency-physics.md","filePath":"litho/conversion-efficiency-physics.md","lastUpdated":1789023840000}'),p={name:"litho/conversion-efficiency-physics.md"};function d(m,a,B,A,_,f){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="转换效率的物理" tabindex="-1">转换效率的物理 <a class="header-anchor" href="#转换效率的物理" aria-label="Permalink to &quot;转换效率的物理&quot;">​</a></h1><div class="epigraph"><p>转换效率是带内 EUV 能量除以打到靶上的激光能量。几个百分点是整厂功耗和收集镜热负荷的杠杆，不是光谱仪上的峰值亮度。</p><footer>—— 据 Bakshi, EUV Lithography；ASML 对 in-band CE 的公开定义</footer></div><p><a href="/litho/co2-drive-laser-chain">上一课</a>把十千瓦级 CO₂ MOPA 送到锡靶。缺口是：红外瓦数不等于中间焦点的带内瓦数。中间隔着等离子体耦合、辐射分支和收集几何。本课钉转换效率（conversion efficiency, CE）的物理定义与上限来自哪里。锡离子为什么在 13.5 nm 亮，留给<a href="/litho/tin-plasma-emission">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>驱动链可以再加一级放大，墙插功率跟着涨。若 CE 停在约 1%（实心滴、无预脉冲），激光白烧、镜子更热、碎屑更猛，IF 仍到不了 <a href="/litho/asml-nxe">NXE</a> 公开的 250 W 级里程碑。<a href="/litho/euv-prepulse">预脉冲</a>把 CE 抬到约 5–6%，是把靶的密度标长改到 CO₂ 能吸收的窗口，不是把放大链再乘一个系数。</p><p>缺口因此是能量分支，不是再画一张 MOPA 框图。打到靶上的激光，一部分被临界密度面反射，一部分变成离子动能和流体力学膨胀，一部分变成宽带辐射；只有落在多层膜约 2% 窗口内的那一份，才进 CE 的分子。</p> \\[\\mathrm{CE} = \\frac{E_{\\mathrm{EUV,in-band}}}{E_{\\mathrm{laser,on-target}}}. \\]<p><span class="marginnote">公开数字通常按主脉冲激光能量归一。把预脉冲能量加进分母，会把同一套实验说成两个 CE。引用时核对原文定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上把 CE 拆成可调的三块：靶（滴径、预脉冲展开、盘的光学厚度）、激光（波长、强度、脉宽、焦斑）和等离子体状态（温度、密度、停留时间）。CO₂ 的临界密度 \\(n_c\\propto\\lambda^{-2}\\)，把吸收区放在相对稀薄的冕，有利于把能量停在带内价态而不是过密反射。短波长固体激光更容易耦进过密区，实验室可以出光，量产 CE 往往更差——这是选 10.6 μm 的效率理由，上一课只写了链，本课才写为什么这条链的波长不能随便换。</p><p>计量在带内通道做：多层膜标定的探测器看 13.5 nm 附近积分，激光量热计看靶上能量。立体角要声明：有的实验报 \\(2\\pi\\) 内的 CE，量产合同是收集镜实际收到、再扣 \\(R_{\\mathrm{col}}\\) 和气体之后的 IF。两者差一个几何因子，不能拿大阪大学单脉冲纪录直接当 NXE 的 CE。</p>',11)),(e(),s(c,null,{default:t(()=>[h(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAS%5B%22%E9%9D%B6%E4%B8%8A%E6%BF%80%E5%85%89%E8%83%BD%E9%87%8F%22%5D%20--%3E%20ABS%5B%22%E5%86%95%E5%8C%BA%E5%90%B8%E6%94%B6%22%5D%0A%20%20ABS%20--%3E%20KIN%5B%22%E7%A6%BB%E5%AD%90%E5%8A%A8%E8%83%BD%20%2F%20%E8%86%A8%E8%83%80%22%5D%0A%20%20ABS%20--%3E%20BB%5B%22%E5%AE%BD%E5%B8%A6%E8%BE%90%E5%B0%84%22%5D%0A%20%20BB%20--%3E%20IB%5B%22%E7%BA%A6%202%25%20%E5%B8%A6%E5%86%85%22%5D%0A%20%20IB%20--%3E%20CE%5B%22CE%20%E5%88%86%E5%AD%90%22%5D%0A%20%20LAS%20--%3E%20REF%5B%22%E4%B8%B4%E7%95%8C%E9%9D%A2%E5%8F%8D%E5%B0%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最优窗口是辐射流体力学的交集。太冷，锡离子价态不够，UTA 暗；太热，能量跑到更高电离和动能，CE 掉、碎屑更硬。Nishihara、Fujioka 等对激光等离子体 EUV 的辐射流体模拟，把这块写成「在膨胀尚未拆完靶之前，把温度钉在数十电子伏」。预脉冲负责把靶送到这个状态，主脉冲负责在微秒寿命里把能量耦进去。</p><p>O&#39;Sullivan 等对锡未分辨跃迁阵列的原子物理给出光谱上限：即使每个激光光子都变成辐射，带内分支比仍受 UTA 宽度与多层窗口重叠限制。CE 的几个百分点不是「工程没做好」，是原子物理加几何收集的乘积。量产再抠的是：在 50 kHz、氢气流和逐渐变脏的收集镜下，把 CE 维持在这个窗口，而不是单次打出纪录。</p><p><span class="marginnote">IF 功率还要乘收集立体角、收集镜反射率和氢柱透过率。CE 高而 \\(R_{\\mathrm{col}}(t)\\) 掉，产能照样垮。本课只钉激光→带内这一段；功率路线课再把整条账乘开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 Sn⁸⁺–Sn¹⁴⁺ 的具体跃迁，那是下一课的辐射。也不把 5–6% 写成与滴径无关的物理常数——发生器改尺寸，膨胀时间和光学厚度都要重调。出处：Bakshi 对 CE 与 LPP 能量流；ASML 对 in-band 定义；Fujioka / Nishihara 等辐射流体工作；O&#39;Sullivan 等锡 UTA 光谱。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CE 是带内 EUV 相对靶上激光的比值，不是全谱亮度。</li><li>波长、靶形态和等离子体温度密度共同决定分支；预脉冲改的是靶，不是定义。</li><li>后课默认：加激光之前先问 CE 窗口还在不在。</li><li>出处：Bakshi；ASML in-band CE；Fujioka、Nishihara、O&#39;Sullivan 等。</li></ul>',8))])}const S=r(p,[["render",d]]);export{u as __pageData,S as default};
